// ==========================================================================
//  LANGUAGE IDENTIFICATION -- the model ML Kit runs, computed here
//
//  The model is langid_model.h, generated by tools/langid/gen_model.py from
//  MediaPipe's Language Detector (Apache License 2.0). It is the model inside
//  ML Kit's language identification (com.google.mlkit:language-id 17.0.6):
//  same graph, same weights byte for byte, same 111 labels. ML Kit's own
//  native library carries the same NGramHash and KmeansEmbeddingLookup code
//  (its error strings and option names are MediaPipe's). Nothing here talks to
//  the network and no TensorFlow Lite is linked: the graph is fixed and small,
//  so its 11 operations are written out below, ported from MediaPipe's source
//  (tools/langid/mediapipe/) and TensorFlow Lite's kernels:
//
//    NGramHash               "^", one token per character, "$"; for n = 1..4,
//                            a hashed id for the n tokens starting at each one
//    KmeansEmbeddingLookup   per n: each id -> 6 codebook rows of 4 floats,
//                            averaged over every position -> 24 floats
//    CONCATENATION           4 x 24 -> 96
//    FULLY_CONNECTED x 3     96 -> 160 -> 200 -> 111; int8 weights, the input
//                            quantized on the fly ("hybrid"); RELU, RELU, none
//    SOFTMAX                 one probability per label of kLidLabels
//
//  The model reads at most the first 126 characters (NGramHash's max_splits of
//  128, less "^" and "$") -- as in ML Kit.
//
//  PROVEN: tools/verify/langid/run.sh -- the token ids against MediaPipe's own
//  C++ (bit for bit, rune tables over every code point) and the probabilities
//  against MediaPipe's LanguageDetector. If this is touched, re-run that.
// ==========================================================================
#pragma once
#include <cmath>
#include <cstddef>
#include <cstdint>
#include "langid_model.h"

// rbsearch of MediaPipe's runetype.c: the last of `rows` rows of `width` runes
// whose first rune is <= c.
static inline const int32_t* lidSearch(int32_t c, const int32_t* t, int rows, int width) {
    while (rows > 1) {
        int m = rows >> 1;
        const int32_t* p = t + m * width;
        if (c >= p[0]) { t = p; rows -= m; } else rows = m;
    }
    return rows && c >= t[0] ? t : nullptr;
}

#define EV_LID_ROWS(t, w) (int)(sizeof(t) / sizeof((t)[0]) / (w))

// utf_isalpharune and utf_tolowerrune: MediaPipe's tables (Unicode 6-era
// letters), not this core's -- the model was trained on what they say.
static inline bool lidIsAlpha(int32_t c) {
    const int32_t* p = lidSearch(c, kLidAlphaRanges, EV_LID_ROWS(kLidAlphaRanges, 2), 2);
    if (p && c >= p[0] && c <= p[1]) return true;
    p = lidSearch(c, kLidAlphaSingles, EV_LID_ROWS(kLidAlphaSingles, 1), 1);
    return p && c == p[0];
}

static inline int32_t lidToLower(int32_t c) {
    const int32_t* p = lidSearch(c, kLidLowerRanges, EV_LID_ROWS(kLidLowerRanges, 3), 3);
    if (p && c >= p[0] && c <= p[1]) return c + p[2] - 1048576;
    p = lidSearch(c, kLidLowerPairs, EV_LID_ROWS(kLidLowerPairs, 3), 3);
    if (p && c >= p[0] && c <= p[1] && !((c - p[0]) & 1)) return c + p[2] - 1048576;
    p = lidSearch(c, kLidLowerSingles, EV_LID_ROWS(kLidLowerSingles, 2), 2);
    if (p && c == p[0]) return c + p[1] - 1048576;
    return c;
}

// utf_charntorune: the bytes one rune takes, with *r set; 0xFFFD and 1 for a
// byte that starts no valid sequence, 0 when the sequence runs past n. Like
// MediaPipe it lets surrogates (ED A0..BF ..) through: they are not letters,
// so they tokenize as a space either way.
static inline int lidDecode(const unsigned char* s, size_t n, int32_t* r) {
    *r = 0xFFFD;
    if (n == 0) return 0;
    int c = s[0];
    if (c < 0x80) { *r = c; return 1; }
    if (n <= 1) return 0;
    int c1 = s[1] ^ 0x80;
    if (c1 & 0xC0) return 1;
    if (c < 0xE0) {
        if (c < 0xC0) return 1;
        int32_t l = ((c << 6) | c1) & 0x7FF;
        if (l <= 0x7F) return 1;
        *r = l;
        return 2;
    }
    if (n <= 2) return 0;
    int c2 = s[2] ^ 0x80;
    if (c2 & 0xC0) return 1;
    if (c < 0xF0) {
        int32_t l = ((((c << 6) | c1) << 6) | c2) & 0xFFFF;
        if (l <= 0x7FF) return 1;
        *r = l;
        return 3;
    }
    if (n <= 3) return 0;
    int c3 = s[3] ^ 0x80;
    if (c3 & 0xC0) return 1;
    if (c < 0xF8) {
        int32_t l = ((((((c << 6) | c1) << 6) | c2) << 6) | c3) & 0x1FFFFF;
        if (l <= 0xFFFF || l > 0x10FFFF) return 1;
        *r = l;
        return 4;
    }
    return 1;
}

// utf_runetochar
static inline int lidEncode(int32_t rune, char* s) {
    uint32_t c = (uint32_t)rune;
    if (c <= 0x7F) { s[0] = (char)c; return 1; }
    if (c <= 0x7FF) { s[0] = (char)(0xC0 | (c >> 6)); s[1] = (char)(0x80 | (c & 0x3F)); return 2; }
    if (c > 0x10FFFF) c = 0xFFFD;
    if (c <= 0xFFFF) {
        s[0] = (char)(0xE0 | (c >> 12)); s[1] = (char)(0x80 | ((c >> 6) & 0x3F)); s[2] = (char)(0x80 | (c & 0x3F));
        return 3;
    }
    s[0] = (char)(0xF0 | (c >> 18)); s[1] = (char)(0x80 | ((c >> 12) & 0x3F));
    s[2] = (char)(0x80 | ((c >> 6) & 0x3F)); s[3] = (char)(0x80 | (c & 0x3F));
    return 4;
}

// MurmurHash64WithSeed (MediaPipe's murmur.cc, Murmur 2.0, little-endian loads).
static inline uint64_t lidMurmur(const char* buf, size_t len, uint64_t seed) {
    const uint64_t kMul = 0xc6a4a7935bd1e995ULL;
    const size_t aligned = len & ~(size_t)7;
    uint64_t hash = seed ^ (len * kMul);
    for (size_t i = 0; i < aligned; i += 8) {
        uint64_t d = 0;
        for (int k = 0; k < 8; k++) d |= (uint64_t)(unsigned char)buf[i + k] << (8 * k);
        d *= kMul;
        d = (d ^ (d >> 47)) * kMul;
        hash = (hash ^ d) * kMul;
    }
    if (len & 7) {
        uint64_t d = 0;
        for (size_t k = 0; k < (len & 7); k++) d |= (uint64_t)(unsigned char)buf[aligned + k] << (8 * k);
        hash = (hash ^ d) * kMul;
    }
    hash = (hash ^ (hash >> 47)) * kMul;
    return hash ^ (hash >> 47);
}

#define EV_LID_TOKENS 128   // kLidMaxSplits: "^", up to 126 characters, "$"

// NGramHash's preprocessing: the token string and where each token starts.
// MediaPipe lowercases the WHOLE input (letters only) and then tokenizes the
// lowercased bytes up to the ORIGINAL byte length. So a letter whose lowercase
// is longer (U+023A -> U+2C65) pushes the tail out, and one whose lowercase is
// shorter (Turkish U+0130 -> 'i', U+1E9E -> U+00DF) makes it read on past its
// string's end: the terminating NUL, then whatever follows -- in a short
// string, more zeros. Each zero is a non-letter, so a space token; here those
// bytes are taken as the zeros they are there. MediaPipe gives exactly these
// probabilities for such text (run.sh); only where the string is long enough
// to live on the heap does what follows the NUL vary from run to run. A
// sequence cut off at the very end makes its lowercasing loop forever; here it
// ends the text.
struct LidTokens {
    char str[EV_LID_TOKENS * 4];
    int start[EV_LID_TOKENS + 1];   // token k is str[start[k] .. start[k+1])
    int count;
};

static inline void lidTokenize(const char* text, size_t len, LidTokens* t) {
    const unsigned char* s = (const unsigned char*)text;
    int at = 0, n = 0;
    t->str[at] = '^';
    t->start[n++] = at++;
    size_t lowered = 0;   // where this character sits in the lowercased bytes
    size_t i = 0;
    bool cut = false;     // the text ended mid-character: tokenizing stops there
    while (i < len && n + 1 < EV_LID_TOKENS) {
        int32_t r;
        int used = lidDecode(s + i, len - i, &r);
        if (used == 0) { cut = true; break; }
        i += used;
        if (lidIsAlpha(r)) r = lidToLower(r);
        char enc[4];
        int bytes = lidEncode(r, enc);
        if (lowered + bytes > len) { cut = true; break; }
        lowered += bytes;
        t->start[n++] = at;
        if (lidIsAlpha(r)) {
            for (int k = 0; k < bytes; k++) t->str[at++] = enc[k];
        } else {
            t->str[at++] = ' ';
        }
    }
    // The characters ran out before the byte length did: the zeros past the
    // lowercased string's end.
    for (; !cut && lowered < len && n + 1 < EV_LID_TOKENS; lowered++) {
        t->start[n++] = at;
        t->str[at++] = ' ';
    }
    t->start[n++] = at;
    t->str[at++] = '$';
    t->start[n] = at;
    t->count = n;
}

// KmeansEmbeddingLookup over the ids NGramHash gives n-grams of length n+1:
// the mean, over every start position, of the 6 codebook rows the id names.
static inline void lidEmbed(const LidTokens& t, int n, float out[24]) {
    static const uint8_t* const kEnc[4] = {kLidEnc0, kLidEnc1, kLidEnc2, kLidEnc3};
    static const float* const kCodebook[4] = {kLidCodebook0, kLidCodebook1, kLidCodebook2, kLidCodebook3};
    float sum[24] = {0};
    for (int s = 0; s < t.count; s++) {
        int end = s + kLidNgramLength[n] < t.count ? s + kLidNgramLength[n] : t.count;
        uint64_t hash = lidMurmur(t.str + t.start[s], (size_t)(t.start[end] - t.start[s]), kLidSeed);
        int id = (int)(hash % (uint64_t)kLidVocab[n]) + 1;
        const uint8_t* code = kEnc[n] + id * 6;
        for (int d = 0; d < 6; d++) {
            const float* row = kCodebook[n] + code[d] * 4;
            for (int k = 0; k < 4; k++) sum[d * 4 + k] += row[k];
        }
    }
    for (int k = 0; k < 24; k++) out[k] = sum[k] / (float)(t.count > 1 ? t.count : 1);
}

// TensorFlow Lite's hybrid FULLY_CONNECTED with asymmetric_quantize_inputs, the
// model's option (fully_connected.cc EvalHybridDense): the input is quantized
// to int8 with its own scale and zero point, the dot products are exact
// integers, and only the result is scaled back to float. The quantizing is
// NeonAsymmetricQuantizeFloats, the one ML Kit's library runs (on x86 too,
// through NEON_2_SSE -- read off its machine code): the range is a FLOAT
// subtraction, the zero point double arithmetic, and each value is rounded
// half away from zero BEFORE the zero point is added (vcvtaq_s32_f32). The
// portable kernel differs in the last two, and one value landing on the other
// side of a .5 moves a probability by up to 0.007.
static inline void lidDense(const float* in, int cols, const int8_t* w, float wScale,
                            const float* bias, int rows, bool relu, float* out) {
    for (int r = 0; r < rows; r++) out[r] = bias[r];
    float lo = 0, hi = 0;   // min(0, min) and max(0, max)
    for (int c = 0; c < cols; c++) { if (in[c] < lo) lo = in[c]; if (in[c] > hi) hi = in[c]; }
    if (lo != hi) {   // all zero: TFLite skips the product, leaving the bias
        const double qmin = -128, qmax = 127;
        const double scale = (double)(hi - lo) / (qmax - qmin);
        const double rmin = lo, rmax = hi;
        const double fromMin = qmin - rmin / scale, fromMax = qmax - rmax / scale;
        const double zero = std::fabs(qmin) + std::fabs(rmin / scale) < std::fabs(qmax) + std::fabs(rmax / scale)
                            ? fromMin : fromMax;
        const int32_t offset = zero <= qmin ? -128 : zero >= qmax ? 127 : (int32_t)(int8_t)std::round(zero);
        const float factor = (float)scale;
        const float inverse = 1.0f / factor;
        int8_t q[200];
        for (int c = 0; c < cols; c++) {
            int32_t v = (int32_t)std::round(in[c] * inverse) + offset;
            q[c] = (int8_t)(v < -128 ? -128 : v > 127 ? 127 : v);
        }
        const float rowScale = factor * wScale;
        for (int r = 0; r < rows; r++) {
            const int8_t* row = w + r * cols;
            int32_t dot = 0;
            for (int c = 0; c < cols; c++) dot += (int32_t)row[c] * ((int32_t)q[c] - offset);
            out[r] += (float)dot * rowScale;
        }
    }
    if (relu) for (int r = 0; r < rows; r++) if (out[r] < 0) out[r] = 0;
}

// The probability of each label of kLidLabels for UTF-8 text. False, with
// nothing written, for empty text: NGramHash refuses it ("Empty input not
// supported.").
static inline bool lidClassify(const char* text, size_t len, float prob[EV_LID_CLASSES]) {
    if (len == 0) return false;
    LidTokens t;
    lidTokenize(text, len, &t);
    float x[96], h1[160], h2[200];
    for (int n = 0; n < 4; n++) lidEmbed(t, n, x + n * 24);
    lidDense(x, 96, kLidWeight0, kLidScale0, kLidBias0, 160, true, h1);
    lidDense(h1, 160, kLidWeight1, kLidScale1, kLidBias1, 200, true, h2);
    lidDense(h2, 200, kLidWeight2, kLidScale2, kLidBias2, EV_LID_CLASSES, false, prob);
    float top = prob[0];
    for (int k = 1; k < EV_LID_CLASSES; k++) if (prob[k] > top) top = prob[k];
    float sum = 0;
    for (int k = 0; k < EV_LID_CLASSES; k++) { prob[k] = std::exp(prob[k] - top); sum += prob[k]; }
    for (int k = 0; k < EV_LID_CLASSES; k++) prob[k] /= sum;
    return true;
}
